import{_ as s,o as a,c as n,a2 as o}from"./chunks/framework.Di-jvWLj.js";const y=JSON.parse('{"title":"Effect Tools & Reconciliation","description":"","frontmatter":{},"headers":[],"relativePath":"guide/effect-tools.md","filePath":"guide/effect-tools.md","lastUpdated":1792495823000}'),t={name:"guide/effect-tools.md"};function l(c,e,p,r,i,d){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="effect-tools-reconciliation" tabindex="-1">Effect Tools &amp; Reconciliation <a class="header-anchor" href="#effect-tools-reconciliation" aria-label="Permalink to &quot;Effect Tools &amp; Reconciliation&quot;">​</a></h1><p>An effect tool is an AI SDK tool whose side effect must apply <strong>at most once per effect key</strong>: a comment, a label, a push, a notification. <code>defineEffectTool()</code> takes the same definition as <code>tool()</code>, plus two optional hooks.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamberu vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> responder = defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;responder&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    model,</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Answer new issues.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    tools: ({ run }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#FF7B84;">        const</span><span style="color:#E6DFDE;"> keyOf = ({ issue }: { issue: number }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E7C58C;"> \`</span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">run</span><span style="color:#E6DFDE;">.</span><span style="color:#E7C58C;">runId</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">:comment:</span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">issue</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">\`</span><span style="color:#E6DFDE;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">        return</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#E6DFDE;">            comment: defineEffectTool({</span></span>
<span class="line"><span style="color:#E6DFDE;">                description: </span><span style="color:#E7C58C;">&#39;Posts a comment on the issue.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">                inputSchema: z.object({ issue: z.number(), body: z.string() }),</span></span>
<span class="line"><span style="color:#958A8B;">                // one comment per run and issue, whatever the body says</span></span>
<span class="line"><span style="color:#E6DFDE;">                effectKey: keyOf,</span></span>
<span class="line"><span style="color:#958A8B;">                // finds a comment an earlier, crashed attempt already posted</span></span>
<span class="line"><span style="color:#E6DFDE;">                alreadyApplied: </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> (key, { issue }) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> findComment(issue, effectMarker(key)),</span></span>
<span class="line"><span style="color:#E6DFDE;">                execute: </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> (input) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> postComment(</span></span>
<span class="line"><span style="color:#E6DFDE;">                    input.issue,</span></span>
<span class="line"><span style="color:#E7C58C;">                    \`</span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">input</span><span style="color:#E6DFDE;">.</span><span style="color:#E7C58C;">body</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">\\n</span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">effectMarker</span><span style="color:#E6DFDE;">(</span><span style="color:#E7C58C;">keyOf</span><span style="color:#E6DFDE;">(</span><span style="color:#E7C58C;">input</span><span style="color:#E6DFDE;">))</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">\`</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">                ),</span></span>
<span class="line"><span style="color:#E6DFDE;">            }),</span></span>
<span class="line"><span style="color:#E6DFDE;">        };</span></span>
<span class="line"><span style="color:#E6DFDE;">    },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><h2 id="what-happens-on-every-call" tabindex="-1">What happens on every call <a class="header-anchor" href="#what-happens-on-every-call" aria-label="Permalink to &quot;What happens on every call&quot;">​</a></h2><p>The engine wraps every effect tool of a run. For each call it computes the effect key and then:</p><ol><li><strong>Recorded result.</strong> If the store holds a result for the key, it returns that result without running anything.</li><li><strong>Remote check.</strong> Otherwise, if the tool has <code>alreadyApplied</code>, it asks whether the effect already exists remotely. A result other than <code>undefined</code> is recorded and returned.</li><li><strong>Execute.</strong> Otherwise it runs <code>execute</code> and records the result.</li></ol><p>A throwing <code>execute</code> (or <code>alreadyApplied</code>) records nothing, so a later retry can still apply the effect. Parallel identical calls within one step share one application.</p><h2 id="effect-keys" tabindex="-1">Effect keys <a class="header-anchor" href="#effect-keys" aria-label="Permalink to &quot;Effect keys&quot;">​</a></h2><p>The default key is <code>&lt;runId&gt;:&lt;toolName&gt;:&lt;sha256 of the canonical JSON input&gt;</code>. Canonical means object keys are sorted, <code>undefined</code> is dropped and <code>toJSON</code> values such as <code>Date</code> are serialized through <code>toJSON</code>. Inputs with <code>BigInt</code> or cycles are not supported.</p><p>With the default key, the same call with the same input in the same run is applied once. Pass <code>effectKey(input, ctx)</code> when &quot;the same effect&quot; means something else, for example one comment per run and issue whatever the body says.</p><h2 id="the-crash-window" tabindex="-1">The crash window <a class="header-anchor" href="#the-crash-window" aria-label="Permalink to &quot;The crash window&quot;">​</a></h2><p>The result is recorded after <code>execute</code> returns. A crash between the side effect and the store write leaves no record, so the retry would apply the effect again. <code>alreadyApplied</code> closes that window: it checks the remote system before acting.</p><p><code>effectMarker(key)</code> returns a hidden HTML comment, <code>&lt;!-- chamberu:effect=&lt;key&gt; --&gt;</code>. Embed it in what the tool creates (a comment body, a pull request description) so <code>alreadyApplied</code> can find it again. Other strategies:</p><ul><li><strong>Set semantics.</strong> Adding a label that is already there changes nothing; such tools need no reconciliation.</li><li><strong>Remote state.</strong> Compare a remote ref or a commit trailer before pushing.</li><li><strong>Idempotency keys.</strong> Send the effect key as the <code>Idempotency-Key</code> of an HTTP API that supports it.</li></ul><p>If recording the result fails after the effect happened, the call still succeeds; the failure is logged and <code>alreadyApplied</code> guards the next retry.</p><h2 id="outside-the-engine" tabindex="-1">Outside the engine <a class="header-anchor" href="#outside-the-engine" aria-label="Permalink to &quot;Outside the engine&quot;">​</a></h2><p><code>wrapToolsForRun(tools, ctx, store)</code> applies the same wrapping to a <code>ToolSet</code> outside the engine, for example in a test or a custom loop. <code>ctx</code> is a <code>RunContext</code> (<code>runId</code>, <code>agent</code>, <code>trigger</code>, <code>signal</code>) and <code>store</code> any <code>IEffectStore</code>. Tools that are not effect tools pass through unchanged.</p><p>Streaming tools work too: when <code>execute</code> returns an async iterable, the last yielded value is the recorded result.</p>`,18)])])}const f=s(t,[["render",l]]);export{y as __pageData,f as default};
